%earth params
R_E = 6371e3; %m
M_E = 5.9722e24; %kg
Gparam = 3.986e14; %mu

%density every 60 km in altitude
arho100 = [100,5.08E-07]; arho160 = [160,1.18E-09]; arho220 = [220,1.66E-10]; 
arho280 = [280,3.94E-11]; arho340 = [340,1.16E-11]; arho400 = [400,3.89E-12];

alt_table = [100,160,220,280,340,400]*1000;
rho_table = [5.08E-07,1.18E-09,1.66E-10,3.94E-11,1.16E-11,3.89E-12];

H = 46e3; %scale height of Eatm % assumption
%satellite params
m_sat1 = 12; %6U CubeSat
A_sat1 = 0.22; %6U CubeSat
C_D = 2.2; %drag coeff in LEO
altitude0 = 400e3;

params.R_E= R_E;  params.mu = Gparam; params.H = H;
params.alt_table = alt_table; params.rho_table = rho_table;
params.m= m_sat1;    params.A = A_sat1;  params.C_D = C_D;
params.useRot = 1;

%initial conditions
r0 = R_E + altitude0;
v_circ = sqrt(params.mu/r0);

x0 = r0; y0=0; z0=0;
vx0 = 0;  vy0 = v_circ; vz0 = 0;

Y0=[x0;y0;z0;vx0;vy0;vz0];

%%

t_final = 100*3600*24;
tspan = [0,t_final];

opts = odeset('RelTol',1e-10,'AbsTol',1e-9, 'Events',@(t,Y) reentry_event(t,Y,params));
[t, Y, te, ye, ie] = ode113(@(t, Y) orbit_dynamics(t, Y, params), tspan, Y0, opts);

x = Y(:,1);
y = Y(:,2);
z = Y(:,3);
vx = Y(:,4);
vy = Y(:,5);
vz = Y(:,6);

r3d = [x,y,z];
v3d = [vx,vy,vz];

r = (vecnorm(r3d,2,2) - params.R_E)/1000;
rm = r*1000;
v = vecnorm(v3d,2,2)/1000;
vm = v*1000;

figure; %[output:812ad985]
plot(r,v) %[output:812ad985]
set(gca, 'XDir', 'reverse'); %[output:812ad985]
%xlim([399.9 400.1])
xlabel("Altitude (km)") %[output:812ad985]
ylabel("Velocity (km\cdots^{-1})") %[output:812ad985]
xline(100, '--r', 'Kármán Line (100 km)', 'LabelVerticalAlignment', 'bottom') %[output:812ad985]
exportgraphics(gcf, 'plots/altitude_vs_velocity.png', 'Resolution', 300) %[output:812ad985]
figure; %[output:5969c602]
plot(t,r) %[output:5969c602]
%xlim([0 5e4])
xlabel("Time (s)") %[output:5969c602]
ylabel("Altitude (km)") %[output:5969c602]
hold on %[output:5969c602]
yyaxis right %[output:5969c602]
plot(t,v) %[output:5969c602]
ylabel("Velocity (km\cdots^{-1})") %[output:5969c602]
exportgraphics(gcf, 'plots/altitude_vs_time.png', 'Resolution', 300) %[output:5969c602]

%reentry func
function [value, isterminal, direction] = reentry_event(~, Y, params)
value = norm(Y(1:3)) - params.R_E - 100e3;  % zero at 100 km altitude
isterminal = 1;    % stop the integration
direction = -1;    % only when altitude is decreasing
end

function dYdTt = orbit_dynamics(t, Y, params)
r = Y(1:3);
v = Y(4:6);
R = norm(r);
altitude1 = R - params.R_E;

omegaE = params.useRot*7.292e-5; %earth atm co-rotation effect rad/s
omegaCrossR = cross([0;0;omegaE], r);
v_rel = v-omegaCrossR;
vr_mag = norm(v_rel);
density = exp(interp1(params.alt_table,log(params.rho_table),altitude1,"linear","extrap"));
a_drag = (1/2*params.C_D*density*params.A*vr_mag*v_rel)/params.m;
a = -params.mu * r / R^3;
a_tot = a-a_drag;
dYdTt = [v; a_tot];

end
% No rotation
params.useRot = 0;
[t_off, Y_off, te_off] = ode113(@(t,Y) orbit_dynamics(t, Y, params), tspan, Y0, opts);

% With rotation
params.useRot = 1;
[t_on, Y_on, te_on] = ode113(@(t,Y) orbit_dynamics(t, Y, params), tspan, Y0, opts);

fprintf('Time for re-entry without Earth rotation: %.2f days', te_on/3600/24) %[output:690495ca]
fprintf('Time for re-entry with Earth rotation: %.2f days', te_off/3600/24) %[output:951373a7]
fprintf('Lifetime increase from rotation: %.1f %%\n', 100*(te_on - te_off)/te_off); %[output:778ef520]

%%
%should only show something when C_D = 0

E=vm.^2/2 - Gparam./rm;
E_frac=(E-E(1))/abs(E(1));
plot(t, E_frac) %[output:6a2891f6]
xlabel("Time") %[output:6a2891f6]
ylabel("Energy") %[output:6a2891f6]

h=vecnorm(cross(r3d,v3d,2),2,2);
hfrac = (h-h(1))/h(1);
plot(t, hfrac) %[output:6a2891f6]
xlabel("Time") %[output:6a2891f6]
ylabel("Angular Momentum") %[output:6a2891f6]

